referenceSolutions.javascript:
export function solve(weights, calls) {
  const args = calls.flat();
  if (args.length < weights.length) return { done: false, remaining: weights.length - args.length };
  return { done: true, value: weights.reduce((sum, w, i) => sum + w * args[i], 0) };
}

